gaMN(){return"\u0422\u043e\u0440\u0433 \u0432\u043e\u0437\u043c\u043e\u0436\u0435\u043d?"},
gaMO(){return"\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0433\u043e\u0442\u043e\u0432\u044b \u0434\u0430\u0442\u044c?"},
