gb7n(){return"\u0423\u0447\u0443\u0441\u044c, \u0443\u0441\u0442\u0430\u043b\u0430 \ud83d\ude29 \u0410 \u0442\u044b?"},
gb7o(){return"\u0425\u043e\u0440\u043e\u0448\u043e! \u041c\u0430\u043c\u0430 \u043e\u043f\u044f\u0442\u044c \u0441\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u043b\u0430, \u043a\u043e\u0433\u0434\u0430 \u043f\u0440\u0438\u0435\u0434\u0435\u0448\u044c"},
